codeExamples.code:
-- Compact small files across the whole table (bin-packing)
OPTIMIZE sales;

-- Compact AND cluster by frequently-filtered, high-cardinality columns
OPTIMIZE sales ZORDER BY (customer_id, product_id);

-- Optimize only recent partitions to limit compute cost
OPTIMIZE sales
WHERE order_date >= current_date() - INTERVAL 7 DAYS
ZORDER BY (customer_id);

-- Enable write-time optimizations at table level
ALTER TABLE sales SET TBLPROPERTIES (
  'delta.autoOptimize.optimizeWrite' = 'true',
  'delta.autoOptimize.autoCompact' = 'true'
);

-- Inspect the OPTIMIZE that compaction/ manual runs produced
DESCRIBE HISTORY sales;

-- Check data skipping effectiveness via the query profile / EXPLAIN
EXPLAIN SELECT * FROM sales WHERE customer_id = 'C12345';
